definition.script:
pipeline {
  agent none

  options {
    buildDiscarder(logRotator(numToKeepStr: '30'))
    skipDefaultCheckout(true)
    timeout(time: 10, unit: 'MINUTES')
  }

  stages {
    stage('Route webhook') {
      steps {
        script {
          def requestedBranch = params.BRANCH_NAME?.trim()
          def requestedBefore = params.GITHUB_BEFORE?.trim() ?: ''
          def requestedAfter = params.GITHUB_AFTER?.trim()
          def requestedTargets = params.FORCE_TARGETS?.trim() ?: ''
          def requestedParallelism = params.MAX_PARALLEL_MODULE_JOBS?.trim() ?: '4'

          if (!(requestedAfter ==~ /^[0-9a-f]{40}$/) || requestedAfter ==~ /^0{40}$/) {
            error 'Webhook router requires a non-zero 40-character GITHUB_AFTER.'
          }
          if (!(requestedParallelism ==~ /^[1-4]$/)) {
            error 'MAX_PARALLEL_MODULE_JOBS must be between 1 and 4.'
          }

          def targetJob
          if (requestedBranch == 'develop') {
            targetJob = 'playsay-platform-dispatch-develop'
          } else if (requestedBranch ==~ /^release\/[0-9]+\.[0-9]+\.[0-9]+$/) {
            targetJob = 'playsay-platform-dispatch-release'
          } else {
            error "Webhook router does not support branch: ${requestedBranch ?: '(empty)'}"
          }

          currentBuild.displayName = "route-${env.BUILD_NUMBER}"
          currentBuild.description = "${requestedBranch} @ ${requestedAfter.take(12)} -> ${targetJob}"
          echo "Routing ${requestedBranch} @ ${requestedAfter} to ${targetJob}"
          build job: targetJob, parameters: [
            string(name: 'BRANCH_NAME', value: requestedBranch),
            string(name: 'GITHUB_BEFORE', value: requestedBefore),
            string(name: 'GITHUB_AFTER', value: requestedAfter),
            string(name: 'FORCE_TARGETS', value: requestedTargets),
            string(name: 'MAX_PARALLEL_MODULE_JOBS', value: requestedParallelism)
          ], wait: false, propagate: false
        }
      }
    }
  }
}
